  ('71000001-0000-0000-0000-000000002401','70000001-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Auto edit-check: Ammonia 32 ppm exceeds the broiler range (0–25 ppm) — check house ventilation and re-measure.'),
  ('71000002-0000-0000-0000-000000002401','70000002-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Initial bird count recorded as 20 but the hatchery delivery note lists 21. Please verify against the placement manifest.'),
  ('71000003-0000-0000-0000-000000002401','70000002-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Confirmed 20 birds placed — one DOA removed before placement. Manifest annotated and re-filed.'),
