  ('71000002-0000-0000-0000-000000003001','70000002-0000-0000-0000-000000003001','10000000-0000-0000-0000-000000000001','Visual tag 120 does not match the RFID ending in 103 on the chute reader log. Please confirm the visual tag is correctly assigned to this animal.'),
  ('71000003-0000-0000-0000-000000003001','70000002-0000-0000-0000-000000003001','10000000-0000-0000-0000-000000000001','Re-scanned at the chute — visual tag 120 and RFID …103 belong to the same heifer. Reader log corrected.'),
  ('71000001-0000-0000-0000-000000000801','70000001-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','CADESI-04 recorded as 22 but the uploaded lesion photographs suggest more extensive truncal involvement. Please re-score against the photo set and confirm.'),
